@@ -1887,7 +1887,6 @@ static ssize_t fuse_dev_do_write(struct fuse_dev *fud,
 		 * Only allow notifications during while the connection is in an
 		 * initialized and connected state
 		 */
-		err = -EINVAL;
 		if (!fch->initialized || !fch->connected)
